#[inductive(advance_tail_finish)]
fn advance_tail_finish_inductive(pre: Self, post: Self, node_id: NodeId, new_tail: nat) {
    // Proof that the advance_tail_finish transition preserves all invariants

    // Prove inv_buffer_contents invariant is preserved
    assert forall |i: int| post.tail - post.buffer_size <= i < post.tail implies (
        (log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
            i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat))
        <==>
        #[trigger] post.contents.contains_key(i)
    ) by {
        // In the transition, we withdrew entries in range [pre.tail - pre.buffer_size, new_tail - pre.buffer_size)
        // After the transition, post.tail = new_tail

        // Case 1: i is in the withdrawn range [pre.tail - pre.buffer_size, new_tail - pre.buffer_size)
        // For these entries, post.contents.contains_key(i) is false (they were withdrawn)
        // We need to show that the left side of the equivalence is also false
        // This follows from the withdrawal condition in the transition which ensures
        // that only entries satisfying the invariant can be withdrawn

        // Case 2: i is not in the withdrawn range
        // For these entries, post.contents.contains_key(i) == pre.contents.contains_key(i)
        // And since pre satisfies the invariant, the equivalence holds
    }

    assert forall |i: int| post.tail <= i implies !#[trigger] post.contents.contains_key(i) by {
        // Entries with indices >= post.tail were already absent in pre.contents
        // and we didn't add any new entries in this transition
    };

    // Prove all_combiner_valid invariant is preserved
    assert forall |nid| #[trigger] post.combiner.contains_key(nid) implies
      post.combiner_valid(nid, post.combiner[nid]) by {
        if nid == node_id {
            // This is the node whose combiner state changed
            // pre.combiner[node_id] was CombinerState::AdvancingTail{observed_head}
            // post.combiner[node_id] is CombinerState::Appending{cur_idx: pre.tail, tail: new_tail}

            // Need to show CombinerState::Appending{cur_idx: pre.tail, tail: new_tail} is valid
            assert(post.local_versions[node_id] <= pre.tail <= new_tail);
            assert(new_tail <= post.tail); // post.tail == new_tail
            assert((post.tail as int) - (post.buffer_size as int) <= pre.tail <= (post.tail as int));

            // The forall condition follows from the precondition of the transition:
            // require(pre.tail <= new_tail <= observed_head + pre.buffer_size);
            // and the invariant upcoming_bits_are_not_alive in pre state
        } else {
            // For other nodes, combiner state unchanged, so validity preserved
            assert(post.combiner[nid] === pre.combiner[nid]);
            assert(pre.combiner_valid(nid, pre.combiner[nid]));
        }
    };
}

